def repl(s, sid, eid, new):
    a = s.index('- id: ' + sid)
    b = s.index('- id: ' + eid) if eid else s.index('open_questions:')
    return s[:a] + new + s[b:]


def must(s, old, new):
    assert old in s, old[:50]
    return s.replace(old, new)


